---@type kanamono.Extra
return {
  ext = ".conf",
  render = function(c, ansi, name)
    local lines = {
      "# vim:ft=kitty",
      "## name: " .. name,
      "## author: kanamono.nvim",
      "## Generated by :KanamonoExtras. Do not edit by hand.",
      "",
      "foreground " .. c.fg,
      "background " .. c.bg,
      "selection_foreground " .. c.fg,
      "selection_background " .. c.surface3,
      "cursor " .. c.fg,
      "cursor_text_color " .. c.bg,
      "url_color " .. c.accent,
      "",
      "active_border_color " .. c.accent,
      "inactive_border_color " .. c.border,
      "bell_border_color " .. c.yellow,
      "",
      "tab_bar_background " .. c.bg,
      "active_tab_foreground " .. c.fg,
      "active_tab_background " .. c.surface2,
      "inactive_tab_foreground " .. c.muted,
      "inactive_tab_background " .. c.bg,
      "",
      "mark1_foreground " .. c.bg,
      "mark1_background " .. c.blue,
      "mark2_foreground " .. c.bg,
      "mark2_background " .. c.yellow,
      "mark3_foreground " .. c.bg,
      "mark3_background " .. c.cyan,
      "",
    }
    for i = 0, 15 do
      lines[#lines + 1] = ("color%d %s"):format(i, ansi[i])
    end
    return table.concat(lines, "\n") .. "\n"
  end,
}
